// Cloudflare Worker entry: the Next.js app (built by @opennextjs/cloudflare) plus the
// Cron Trigger that runs background work every 2 minutes (wrangler.jsonc "triggers").
// Generated by `opennextjs-cloudflare build` (worker.ts is bundled by wrangler, not type-checked).
import app from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

export default {
  fetch: app.fetch,

  /**
   * Calls the app's own /api/cron/tick in-process (no network hop). A scheduled run may last
   * several minutes, so the tick gets a long budget (TICK_BUDGET_MS) for slow AI jobs.
   */
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const res = await app.fetch(
      new Request("https://crm.internal/api/cron/tick", {
        method: "POST",
        headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
      }),
      env,
      ctx,
    );
    if (!res.ok) console.error(`[cron] tick returned ${res.status}: ${await res.text()}`);
  },
};
